    solution: '恢复 DashboardLayout 固定侧栏；仅把 WorkbenchQuickNav 改为默认透明窄触发区，hover 或键盘 focus 时展开为完整按钮。',
    prevention: '涉及左侧按钮/侧栏的需求要先确认作用域，区分全局导航、作品编辑器快速导航和业务面板侧栏；全局布局改动必须检查首页。',
    keywords: ['首页', '左侧导航', '快速导航', 'WorkbenchQuickNav', 'DashboardLayout', 'hover', '作用域'],
    updatedAt: '2026-06-04',
