    title: '剧情链空链候选后几条漂移成第一章续写',
    area: '作品编辑器 / 生成剧情链 / 空剧情链开头候选',
    symptom: '空剧情链生成 5 个候选时，前几条像第一章开场，但后几条会写成系统已激活、主角开始兑换资源、事件已经发生后的推进内容，更像第一章后半段或第二章。',
    cause: '提示词只强调“同一进度”和“第一章开头”，没有定义第一章开场必须包含读者首次进入故事时的主角处境、场景、压力或异变触发，模型容易把后续规划也当作开头候选。',
    solution: '在剧情链请求、输出格式规则和剧情链2种子提示词里补充空链专用硬规则：每条候选都必须从真正的第一章第一幕写起，禁止默认系统已激活、奖励已发放、战斗已开始、学校已爆炸或任务已推进到中段。',
    prevention: '凡是要求“同批开头候选”的提示词，都要同时约束候选进度和第一幕起点，避免模型用候选编号暗中推进时间线。',
