    solution: '细纲卡片空内容高度改为原来一半；有内容时按估算行数撑开，最高仍为原来的 260px；超过高度后在 textarea 内部滚动，并复用 scrollbar-scroll-only，平时隐藏滚动条，滚动时短暂显示滑块。',
