    symptom: 'webview 使用 allowpopups，主窗口 window.open 会直接 openExternal，webviewRef 使用 any，安全和类型边界都偏松。',
    cause: '内置浏览器为了方便打开网页保留了宽松默认值，没有限制外部 URL 协议，也没有给 Electron webview 补专用类型。',
